// Force a LoadLibraryA call inside the target via thread-hijack (no done-flag
// path, we re-enumerate modules afterwards). Kept for the rare case where a
// custom dependency must be loaded at runtime; manual-map stage A no longer
// uses this (it would deadlock on a CREATE_SUSPENDED target).
static uintptr_t MM_RemoteLoadLibrary(HANDLE hProcess, DWORD pid, const char *dllName)
{
  HMODULE k = GetModuleHandleA("kernel32.dll");
  if(!k)
    return 0;
  uintptr_t loadLibA = (uintptr_t)GetProcAddress(k, "LoadLibraryA");
  if(!loadLibA)
    return 0;

  size_t len = strlen(dllName) + 1;
  void *remoteStr =
      VirtualAllocEx(hProcess, NULL, (len + 16) & ~size_t(15), MEM_COMMIT | MEM_RESERVE,
                     PAGE_READWRITE);
  if(!remoteStr)
    return 0;
  SIZE_T n = 0;
  if(!WriteProcessMemory(hProcess, remoteStr, dllName, len, &n) || n != len)
  {
    VirtualFreeEx(hProcess, remoteStr, 0, MEM_RELEASE);
    return 0;
  }

  rdcarray<uintptr_t> args;
  args.push_back((uintptr_t)remoteStr);
  uint64_t ret = 0;
  bool ok = ThreadHijackCall(hProcess, pid, loadLibA, args, &ret, "MM-LoadLibraryA");

  VirtualFreeEx(hProcess, remoteStr, 0, MEM_RELEASE);

  if(!ok)
    return 0;

  // Re-enumerate so we get a stable HMODULE; LoadLibraryA's return is the
  // module base on success but a freshly-loaded module may not be visible to
  // Toolhelp until the loader finishes its bookkeeping.
  rdcstr lower = strlower(rdcstr(dllName));
  uintptr_t base = MM_FindRemoteModuleBase(pid, lower.c_str());
  if(!base)
    base = (uintptr_t)ret;
  return base;
}

