                        : GetProcAddress(localM, MAKEINTRESOURCEA(ordinal));
  if(!fp)
    return 0;

  wchar_t modPath[MAX_PATH] = {};
  if(!GetModuleFileNameW(localM, modPath, MAX_PATH))
    return 0;
